import{_ as d,a as r,b as o,c as e,d as a,e as n,f as s,g as l,h,i,j as p}from"./chunks/core-repo-contribution.4e790OQG.js";import{_ as b,o as g,c as u,R as c}from"./chunks/framework.CGdQ6rU-.js";const C=JSON.parse('{"title":"Web3.0 开源生态：华语开发者贡献洞察","description":"","frontmatter":{},"headers":[],"relativePath":"web3.md","filePath":"web3.md","lastUpdated":1783589798000}'),m={name:"web3.md"};function q(k,t,W,_,f,P){return g(),u("div",null,[...t[0]||(t[0]=[c('<h1 id="web3-0-开源生态-华语开发者贡献洞察" tabindex="-1">Web3.0 开源生态：华语开发者贡献洞察 <a class="header-anchor" href="#web3-0-开源生态-华语开发者贡献洞察" aria-label="Permalink to &quot;Web3.0 开源生态：华语开发者贡献洞察&quot;">​</a></h1><h2 id="报告说明" tabindex="-1">报告说明 <a class="header-anchor" href="#报告说明" aria-label="Permalink to &quot;报告说明&quot;">​</a></h2><h3 id="研究背景" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景" aria-label="Permalink to &quot;研究背景&quot;">​</a></h3><p>本报告是《2025 中国开源年度报告》Web3.0 洞察篇的数据支撑文档，由 OpenBuild 和 Web3insight.ai 承担分析与撰写工作。</p><p>Web3.0 的底层是开源协议，无论是以太坊、比特币还是 Solana，所有链上基础设施都以开源形式构建、维护和演化。华语开发者在这些协议上的贡献规模与质量，是中国开源社区参与全球技术协作的重要切面，却长期缺乏系统性的数据呈现。</p><p>本报告尝试回答三个问题：</p><ul><li>华语开发者对全球 Web3.0 开源协议的贡献规模与质量如何？</li><li>过去五年，华语社区的开源协议选择发生了哪些结构性迁移？</li><li>华语开发者在开源贡献深度上面临哪些瓶颈，如何突破？</li></ul><h3 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h3><p><strong>主要数据：Electric Capital Open Source Developer Data</strong></p><p>Electric Capital 是专注于区块链原生风险投资的基金，自 2019 年起持续维护全球最权威的 Web3.0 开发者活跃度数据集。该数据集覆盖：</p><ul><li>全球超过 300 万名开发者在区块链相关开源仓库的 Commit 活动</li><li>500+ 区块链生态的开发者归因</li><li>时间跨度：2008 年至今（本报告使用版本 20260321T133239，数据截至 2026 年 3 月 13 日）</li><li>授权协议：CC BY 4.0（允许自由使用与二次传播，需注明来源）</li><li>数据地址：<a href="https://data.opendevdata.org" target="_blank" rel="noreferrer">https://data.opendevdata.org</a></li></ul><p><strong>补充数据：2025 Web3.0 华语开发者调研报告</strong></p><p>由 OpenBuild、GCC、登链、Creators、OpenCAS 联合发起，Web3insight.ai 提供数据分析，共收集 220 份有效问卷（2025 年末），覆盖华语 Web3.0 开发者的职业路径、技术偏好、收入结构与开源参与现状。本报告在各章节中引用其定性洞察，与 Electric Capital 量化数据形成交叉印证。</p><div class="tip custom-block"><p class="custom-block-title">延伸阅读：OpenBuild Web3 Developer Report</p><p>本文引用的华语开发者调研与后续年度更新，将持续整理在 OpenBuild 开发者报告站点。需要查看完整图表、方法说明和历史版本，可访问：<a href="https://report.openbuild.xyz/" target="_blank" rel="noreferrer">https://report.openbuild.xyz/</a></p><p>2025 华语开发者报告：<a href="https://report.openbuild.xyz/zh/2025/" target="_blank" rel="noreferrer">https://report.openbuild.xyz/zh/2025/</a></p><p>源仓库：<a href="https://github.com/openbuildxyz/web3-chinese-speaking-devs-report" target="_blank" rel="noreferrer">https://github.com/openbuildxyz/web3-chinese-speaking-devs-report</a></p></div><h3 id="数据局限性" tabindex="-1">数据局限性 <a class="header-anchor" href="#数据局限性" aria-label="Permalink to &quot;数据局限性&quot;">​</a></h3><p><strong>地理归因覆盖率问题</strong>：Electric Capital 数据集中，约 87 万名开发者（占全体约 27%）有明确的地理位置记录。中国开发者在 GitHub 上填写地理信息的比例显著低于欧美，导致华语开发者的统计数字系统性偏低。本报告基于 GitHub Octoverse 等交叉数据估算，华语开发者的实际规模约为有记录数字的 <strong>3-4 倍</strong>。</p><p><strong>月活开发者（MAD）定义</strong>：以「过去 30 天内在区块链相关开源仓库有至少 1 次有效 Commit」作为计量标准，偏向核心贡献者，不包含仅阅读代码、提交 Issue 或参与讨论的开发者。</p><p><strong>生态归因方法</strong>：一个开发者可能同时活跃于多个生态（multichain 开发者），各生态开发者数量之和大于全局总量。本报告中华语占比等数据均基于同一口径计算。</p><p><strong>开源数据为主</strong>：基于 GitHub 开源贡献数据为主，未参与开源或 Private 方式贡献的开发者可能无法被纳入统计，因此可能与感官上会有偏差。</p><h3 id="阅读指引" tabindex="-1">阅读指引 <a class="header-anchor" href="#阅读指引" aria-label="Permalink to &quot;阅读指引&quot;">​</a></h3><table><thead><tr><th>章节</th><th>核心问题</th></tr></thead><tbody><tr><td>一、全球趋势</td><td>Web3.0 开源协议贡献者的长期走势与职业化程度</td></tr><tr><td>二、全球位置</td><td>华语贡献者在全球开源协议中的真实占比与「隐形」现象</td></tr><tr><td>三、生态分布</td><td>华语开发者在哪些开源协议中贡献最活跃</td></tr><tr><td>四、偏好迁移</td><td>2021-2025 华语社区的开源协议选择迁移路径</td></tr><tr><td>五、城市分布</td><td>中国大陆 Web3.0 开源贡献者的空间结构</td></tr><tr><td>六、协议健康度</td><td>主要 Web3.0 开源协议的贡献者健康度全景</td></tr><tr><td>七、开源贡献</td><td>华语开发者的贡献深度现状与改进路径</td></tr><tr><td>八、建议与展望</td><td>给开发者个体、开源社区和生态方的行动建议</td></tr></tbody></table><hr><h2 id="一、全球-web3-0-开源贡献者规模趋势" tabindex="-1">一、全球 Web3.0 开源贡献者规模趋势 <a class="header-anchor" href="#一、全球-web3-0-开源贡献者规模趋势" aria-label="Permalink to &quot;一、全球 Web3.0 开源贡献者规模趋势&quot;">​</a></h2><p>在开源世界，一个协议是否健康，最终要看有多少人持续往代码库里提交贡献，而不是价格走势或社交媒体声量。Web3.0 所有基础协议均以开源形式运作，贡献者数量的长期走势是判断这个生态能否持续演化的核心指标。</p><h3 id="_1-1-贡献者质量-2025-年峰值比-2022-年更扎实" tabindex="-1">1.1 贡献者质量：2025 年峰值比 2022 年更扎实 <a class="header-anchor" href="#_1-1-贡献者质量-2025-年峰值比-2022-年更扎实" aria-label="Permalink to &quot;1.1 贡献者质量：2025 年峰值比 2022 年更扎实&quot;">​</a></h3><p><img src="'+d+'" alt="全体月活开发者 vs 全职开发者（2022–2026）"></p><table><thead><tr><th>时间</th><th>月活开发者</th><th>全职开发者</th><th>全职占比</th></tr></thead><tbody><tr><td>2022-01</td><td>31,394</td><td>7,879</td><td>25.1%</td></tr><tr><td>2022-06</td><td>34,553</td><td>9,511</td><td>27.5%</td></tr><tr><td>2022-12</td><td>31,716</td><td>9,617</td><td>30.3%</td></tr><tr><td>2023-12</td><td>31,729</td><td>9,665</td><td>30.5%</td></tr><tr><td>2024-06</td><td>36,857</td><td>10,278</td><td>27.9%</td></tr><tr><td>2025-05</td><td>44,261</td><td>10,973</td><td>24.8%</td></tr><tr><td>2026-03</td><td>29,679</td><td>9,291</td><td>31.3%</td></tr></tbody></table><p>2025 年 5 月月活贡献者达历史峰值 <strong>4.4 万</strong>，超越 2022 年牛市高点（3.5 万）。2026 年初回调至约 <strong>2.97 万</strong>（YoY -15%），但全职贡献者相对稳定在 9,000+。</p><p>关键数据：<strong>全职贡献者占比从 2022 年的 25% 升至 2026 年的 31%</strong>。全职贡献者指每月持续在开源仓库提交代码的核心维护者。其占比提升意味着 Web3.0 开源协议的长期维护能力在增强，即使整体贡献者数量在市场周期中波动，协议的底层维护力量并未随之瓦解。</p><blockquote><p><strong>洞察一</strong>：Web3.0 开源协议正在完成从「热度驱动」到「核心维护者职业化」的深层转变。熊市是筛选器，留下来的是真正的长期建设者。开源协议的韧性，来自这批不随市场走的全职贡献者。</p></blockquote><hr><h2 id="二、华语开发者在全球开源协议中的位置" tabindex="-1">二、华语开发者在全球开源协议中的位置 <a class="header-anchor" href="#二、华语开发者在全球开源协议中的位置" aria-label="Permalink to &quot;二、华语开发者在全球开源协议中的位置&quot;">​</a></h2><p>在主流 Web3.0 开源协议的贡献者名单里，中文名字极为罕见，无论是 Ethereum 客户端的核心维护者，还是 Solana 运行时的主要提交者，华语开发者几乎是「隐形」的。但这种隐形，是真实的缺席，还是统计方法导致的系统性低估？</p><h3 id="_2-1-全球-web3-0-开发者国家分布-近一年-有地理记录" tabindex="-1">2.1 全球 Web3.0 开发者国家分布（近一年，有地理记录） <a class="header-anchor" href="#_2-1-全球-web3-0-开发者国家分布-近一年-有地理记录" aria-label="Permalink to &quot;2.1 全球 Web3.0 开发者国家分布（近一年，有地理记录）&quot;">​</a></h3><p><img src="'+r+'" alt="全球 Web3.0 国家分布 Top 10（月活开发者）"></p><table><thead><tr><th>排名</th><th>国家</th><th>活跃开发者</th><th>占比</th></tr></thead><tbody><tr><td>1</td><td>印度</td><td>4,768</td><td>28.1%</td></tr><tr><td>2</td><td>美国</td><td>3,645</td><td>21.5%</td></tr><tr><td>3</td><td>尼日利亚</td><td>1,088</td><td>6.4%</td></tr><tr><td><strong>4</strong></td><td><strong>中国（大陆）</strong></td><td><strong>871</strong></td><td><strong>5.1%</strong></td></tr><tr><td>5</td><td>英国</td><td>852</td><td>5.0%</td></tr><tr><td>6</td><td>加拿大</td><td>763</td><td>4.5%</td></tr><tr><td>7</td><td>巴西</td><td>762</td><td>4.5%</td></tr><tr><td>8</td><td>德国</td><td>733</td><td>4.3%</td></tr><tr><td>9</td><td>法国</td><td>692</td><td>4.1%</td></tr><tr><td>10</td><td>印度尼西亚</td><td>674</td><td>4.0%</td></tr></tbody></table><blockquote><p>⚠️ <strong>统计落差说明</strong>：上表数据仅基于有地理位置记录的约 27% 开发者。中国开发者在 GitHub 填写地理信息的比例显著低于欧美，导致华语贡献者数量被系统性低估。综合 GitHub Octoverse 等交叉数据估算，华语开发者（含中国台湾、中国香港）在全球 Web3.0 开源生态的真实占比可能接近 <strong>15-20%</strong>，是当前统计数字的 3-4 倍。</p></blockquote><h3 id="_2-2-ethereum-生态国家分布-近一年" tabindex="-1">2.2 Ethereum 生态国家分布（近一年） <a class="header-anchor" href="#_2-2-ethereum-生态国家分布-近一年" aria-label="Permalink to &quot;2.2 Ethereum 生态国家分布（近一年）&quot;">​</a></h3><p><img src="'+o+'" alt="Ethereum 生态国家分布 Top 10（月活开发者）"></p><table><thead><tr><th>排名</th><th>国家/地区</th><th>开发者数</th><th>占比</th></tr></thead><tbody><tr><td>1</td><td>印度</td><td>2,830</td><td>38.8%</td></tr><tr><td>2</td><td>美国</td><td>1,797</td><td>24.7%</td></tr><tr><td>3</td><td>中国（大陆）</td><td>496</td><td>6.8%</td></tr><tr><td>4</td><td>英国</td><td>415</td><td>5.7%</td></tr><tr><td>5</td><td>巴西</td><td>391</td><td>5.4%</td></tr><tr><td>附</td><td>中国台湾</td><td>116</td><td>1.6%</td></tr><tr><td>附</td><td>中国香港</td><td>84</td><td>1.2%</td></tr></tbody></table><p><em>中国台湾、中国香港为附录数据，不参与排名</em></p><p>中国大陆排名第3（496人，6.8%）。若合并中国台湾（116人）和中国香港（84人），华语合计占 <strong>9.6%</strong>，是 Ethereum 生态第三大语言群体。</p><p><strong>来源印证</strong>：《2025 Web3.0 华语开发者调研报告》揭示了「隐形」的根本原因：英语协作能力是最核心的可见度门槛。绝大多数华语开发者能独立阅读英文文档，但能流畅参与国际协议 PR Review、提交 RFC 或参与核心协议讨论的比例极少。华语开发者往往「在场但不发声」，代码贡献真实存在，但缺乏在国际开源社区中的话语权积累。</p><blockquote><p><strong>洞察二</strong>：华语开发者对全球 Web3.0 开源协议的贡献被严重低估，既有统计口径问题，也有真实的参与深度不足。提升华语社区在国际开源协议中的可见度，需要两个方向同时发力：一方面是开发者个体提升英文协作能力，另一方面是生态方与社区组织主动建设中文技术文档，降低贡献门槛。</p></blockquote><hr><h2 id="三、华语开发者在主要开源协议中的分布" tabindex="-1">三、华语开发者在主要开源协议中的分布 <a class="header-anchor" href="#三、华语开发者在主要开源协议中的分布" aria-label="Permalink to &quot;三、华语开发者在主要开源协议中的分布&quot;">​</a></h2><p>不同开源协议对华语开发者的吸引力，折射出华语社区对技术路线的真实选择。哪些协议的代码库里华语贡献者最集中？华语占比高的协议，往往意味着中文文档和社区资源相对完善，或者恰恰相反，意味着华语社区在早期就深度参与了该协议的构建。</p><h3 id="华语开发者在主要开源协议中的贡献分布-近一年" tabindex="-1">华语开发者在主要开源协议中的贡献分布（近一年） <a class="header-anchor" href="#华语开发者在主要开源协议中的贡献分布-近一年" aria-label="Permalink to &quot;华语开发者在主要开源协议中的贡献分布（近一年）&quot;">​</a></h3><p><img src="'+e+'" alt="华语开发者生态分布（中国大陆 vs 港台地区，月活）"></p><table><thead><tr><th>生态</th><th>中国大陆</th><th>港台地区</th><th>华语合计</th><th>全球有记录</th><th>华语占比</th></tr></thead><tbody><tr><td>Ethereum</td><td>496</td><td>200</td><td>696</td><td>48,112</td><td><strong>1.4%</strong></td></tr><tr><td>Solana</td><td>269</td><td>71</td><td>340</td><td>26,543</td><td>1.3%</td></tr><tr><td>Sui</td><td>111</td><td>41</td><td>152</td><td>6,138</td><td><strong>2.5%</strong> ⬆️</td></tr><tr><td>Base</td><td>99</td><td>42</td><td>141</td><td>12,699</td><td>1.1%</td></tr><tr><td>BNB Chain</td><td>107</td><td>33</td><td>140</td><td>7,232</td><td>1.9%</td></tr><tr><td>Bitcoin</td><td>113</td><td>26</td><td>139</td><td>8,646</td><td>1.6%</td></tr><tr><td>Polygon</td><td>104</td><td>27</td><td>131</td><td>10,830</td><td>1.2%</td></tr><tr><td>Arbitrum</td><td>84</td><td>38</td><td>122</td><td>7,725</td><td>1.6%</td></tr><tr><td>Cosmos</td><td>34</td><td>10</td><td>44</td><td>2,032</td><td><strong>2.2%</strong></td></tr><tr><td>Starknet</td><td>24</td><td>8</td><td>32</td><td>3,561</td><td>0.9%</td></tr><tr><td>Stellar</td><td>12</td><td>0</td><td>12</td><td>5,546</td><td><strong>0.2%</strong> ⬇️</td></tr></tbody></table><p><strong>关键发现：</strong></p><ul><li><strong>Sui 华语占比 2.5%</strong>，是所有大型生态中最高，超过 Ethereum（1.4%）近一倍。Move 语言在华语社区存在聚集效应</li><li><strong>Cosmos 华语占比 2.2%</strong>，与 Tendermint 时代以来的华语社区积累有关</li><li><strong>BNB Chain 华语占比仅 1.9%</strong>，华语开发者的实际贡献比例与该链的华语社区影响力并不匹配</li><li><strong>Stellar 华语占比 0.2%</strong>，中文技术文档和社区基础设施几乎为零</li></ul><p><strong>来源印证</strong>：调研报告显示，公链关注度中 Ethereum 遥遥领先，Move 语言被提及为「最值得学的第二外语」，与 Sui 华语高占比高度吻合。开发者的实际行动（commit 数据）和问卷意向一致。</p><blockquote><p><em>图：华语开发者公链关注度分布（来源：2025 Web3.0华语开发者调研报告）</em><img src="'+a+'" alt="华语开发者公链关注度"></p></blockquote><blockquote><p><strong>洞察三</strong>：Sui 生态中华语开发者的高占比，既是优势也意味着责任。中文文档、教程和社区支持的严重缺位，是亟需填补的空白。</p></blockquote><hr><h2 id="四、华语社区的开源协议选择迁移-2021-2025" tabindex="-1">四、华语社区的开源协议选择迁移（2021-2025） <a class="header-anchor" href="#四、华语社区的开源协议选择迁移-2021-2025" aria-label="Permalink to &quot;四、华语社区的开源协议选择迁移（2021-2025）&quot;">​</a></h2><p>五年间，华语开发者在哪些开源协议上持续提交贡献？这张变化图呈现的不只是市场偏好，它记录了华语社区在开源技术路线上的集体判断与迁移轨迹。</p><h3 id="华语开发者在主要开源协议的年度活跃贡献数-去重" tabindex="-1">华语开发者在主要开源协议的年度活跃贡献数（去重） <a class="header-anchor" href="#华语开发者在主要开源协议的年度活跃贡献数-去重" aria-label="Permalink to &quot;华语开发者在主要开源协议的年度活跃贡献数（去重）&quot;">​</a></h3><p><img src="'+n+'" alt="主要生态华语开发者数量变化（2021–2025）"></p><table><thead><tr><th>年份</th><th>Ethereum</th><th>Solana</th><th>BNB Chain</th><th>Sui</th><th>Bitcoin</th><th>TON</th><th>Aptos</th></tr></thead><tbody><tr><td>2021</td><td>252</td><td>139</td><td>86</td><td>8</td><td>49</td><td>5</td><td>13</td></tr><tr><td>2022</td><td>528</td><td>201</td><td><strong>160</strong></td><td>57</td><td>47</td><td>17</td><td>84</td></tr><tr><td>2023</td><td>425</td><td>149</td><td>120</td><td>90</td><td>72</td><td>35</td><td>63</td></tr><tr><td>2024</td><td>446</td><td><strong>334</strong></td><td>74</td><td><strong>204</strong></td><td>107</td><td>99</td><td>69</td></tr><tr><td>2025</td><td><strong>670</strong></td><td>352</td><td>132</td><td>170</td><td>139</td><td>44</td><td>65</td></tr></tbody></table><p><strong>四条关键曲线：</strong></p><p><strong>BNB Chain 开源贡献衰退</strong>：活跃贡献者从 2022 年高点 160 人跌至 2024 年 74 人（<strong>-54%</strong>）。数据表明，BNB Chain 开源协议的维护活跃度未能支撑华语社区的持续参与，贡献数据与外界叙事之间存在明显落差。</p><p><strong>Solana 开源社区 V 形复苏</strong>：2023 年市场事件冲击后贡献者跌至 149 人，2024 年反弹至 334 人（+<strong>124%</strong>）。Solana 开源社区在低谷期持续维护核心仓库，是吸引华语贡献者回流的关键。技术路线的持续投入，比市场情绪更有说服力。</p><p><strong>Sui 协议华语贡献者持续增长</strong>：从 2021 年的 8 人增至 2024 年的 204 人（<strong>+2450%</strong>）。Move 语言作为新兴智能合约范式，华语社区在协议早期便大规模参与，形成了持续的贡献积累，而非热点型涌入。</p><p><strong>TON 贡献者昙花一现</strong>：2024 年爆发至 99 人后快速回落至 44 人。贡献者跟随热度涌入，但 TON 开源协议的文档质量、工具链成熟度和社区响应速度未能留住他们，印证了「热点驱动型参与」本身的局限性。</p><p><strong>来源印证</strong>：调研报告指出，华语开发者选择协议的核心考量依次是：生态规模与机会、技术路线的长期性、社区中文支持质量。中文文档和开源社区支持的质量，直接影响华语开发者能否在一个协议上持续积累贡献。</p><blockquote><p><strong>洞察四</strong>：华语开发者的开源协议选择，是生态开源健康度的先行指标。一个协议能否留住华语贡献者，核心在于：技术路线有长期价值、开源社区在低谷期持续维护、中文文档与贡献路径清晰可见。</p></blockquote><hr><h2 id="五、中国大陆开源贡献者城市分布" tabindex="-1">五、中国大陆开源贡献者城市分布 <a class="header-anchor" href="#五、中国大陆开源贡献者城市分布" aria-label="Permalink to &quot;五、中国大陆开源贡献者城市分布&quot;">​</a></h2><p>Web3.0 开源贡献者的空间分布，折射出中国开源生态的区域格局：哪些城市聚集了最多向 Web3.0 协议持续提交贡献的开发者？</p><h3 id="web3-0-开源贡献者城市-top-10-近一年-有地理记录" tabindex="-1">Web3.0 开源贡献者城市 Top 10（近一年，有地理记录） <a class="header-anchor" href="#web3-0-开源贡献者城市-top-10-近一年-有地理记录" aria-label="Permalink to &quot;Web3.0 开源贡献者城市 Top 10（近一年，有地理记录）&quot;">​</a></h3><p><img src="'+s+'" alt="中国城市 Web3.0 活跃开发者分布 Top 10"></p><table><thead><tr><th>排名</th><th>城市</th><th>活跃开发者</th><th>占华语合计</th></tr></thead><tbody><tr><td>1</td><td>北京</td><td>171</td><td>12.4%</td></tr><tr><td>2</td><td>上海</td><td>168</td><td>12.2%</td></tr><tr><td>3</td><td>杭州</td><td>99</td><td>7.2%</td></tr><tr><td>4</td><td>深圳</td><td>94</td><td>6.8%</td></tr><tr><td>5</td><td>成都</td><td>44</td><td>3.2%</td></tr><tr><td>6</td><td>广州</td><td>32</td><td>2.3%</td></tr><tr><td>7</td><td>武汉</td><td>18</td><td>1.3%</td></tr><tr><td>8</td><td>南京</td><td>15</td><td>1.1%</td></tr><tr><td>9</td><td>西安</td><td>11</td><td>0.8%</td></tr><tr><td>10</td><td>厦门</td><td>10</td><td>0.7%</td></tr></tbody></table><p><strong>三个值得关注的现象：</strong></p><p><strong>双中心而非单极</strong>：北京（171）和上海（168）高度接近，合计约占 24.6%，远低于传统互联网「北上深合计 75%+」的集中度。Web3.0 开源贡献的去中心化特性，真实映射到了地理分布的去集中化上。</p><p><strong>杭州超越深圳</strong>：杭州以 99 人超越深圳（94 人）排名第三。杭州拥有活跃的区块链技术开源社区（如登链学院、多个 EVM 工具链维护团队），加之浙大系工程师文化，形成了较强的开源贡献氛围。</p><p><strong>成都西部开源贡献中心</strong>：成都以 44 人稳居西部首位。Dapp-Learning、HOH 等活跃的华语 Web3.0 开源学习社区在成都有重要节点，这类「以学习带动贡献」的开源社区模式，是成都开源贡献者集聚的重要原因。</p><p><strong>来源印证</strong>：调研报告揭示了「地理套利」现象：大量开发者选择居住在二线城市，以国内生活成本为基准，领取美元或稳定币薪酬，实现实际购买力最大化。这解释了为什么 Web3.0 的城市分布远比互联网均匀。当工作地点不再等于雇主城市，开发者会更理性地选择生活成本、宜居性与社区密度的平衡点。</p><blockquote><p><em>图：华语开发者地理分布（来源：2025 Web3.0华语开发者调研报告）</em><img src="'+l+'" alt="华语开发者地理分布"></p></blockquote><blockquote><p><strong>洞察五</strong>：Web3.0 的远程协作文化正在重塑中国开发者的空间分布格局。杭州、成都、武汉等城市正在成为新的 Web3.0 人才聚集地，「北上深」对技术人才的垄断性正在被削弱。</p></blockquote><hr><h2 id="六、主要-web3-0-开源协议贡献者健康度-2026-03" tabindex="-1">六、主要 Web3.0 开源协议贡献者健康度（2026-03） <a class="header-anchor" href="#六、主要-web3-0-开源协议贡献者健康度-2026-03" aria-label="Permalink to &quot;六、主要 Web3.0 开源协议贡献者健康度（2026-03）&quot;">​</a></h2><p>衡量一个开源协议的健康度，不能只看贡献者总量，还要看贡献者结构：全职维护者的比例（长期可持续性）、新贡献者的流入（生态活力）、贡献者的独占性（社区黏性）。下表从六个维度呈现 15 个主要 Web3.0 开源协议的贡献者健康快照。</p><h3 id="主要开源协议贡献者健康度总览" tabindex="-1">主要开源协议贡献者健康度总览 <a class="header-anchor" href="#主要开源协议贡献者健康度总览" aria-label="Permalink to &quot;主要开源协议贡献者健康度总览&quot;">​</a></h3><table><thead><tr><th>生态</th><th>月活开发者</th><th>YoY</th><th>全职占比</th><th>新人占比</th><th>独占占比</th><th>华语占比*</th></tr></thead><tbody><tr><td>Ethereum</td><td>10,926</td><td>-23%</td><td>33%</td><td>38%</td><td>45%</td><td>1.4%</td></tr><tr><td>Solana</td><td>3,904</td><td>-26%</td><td>29%</td><td>45%</td><td>49%</td><td>1.3%</td></tr><tr><td>Bitcoin</td><td>2,941</td><td>-15%</td><td>33%</td><td>39%</td><td>56%</td><td>1.6%</td></tr><tr><td><strong>Base</strong></td><td><strong>2,525</strong></td><td><strong>+25%</strong></td><td>23%</td><td><strong>52%</strong></td><td>20%</td><td>1.1%</td></tr><tr><td>Polygon</td><td>2,032</td><td>+3%</td><td>27%</td><td>49%</td><td>19%</td><td>1.2%</td></tr><tr><td>Arbitrum</td><td>1,829</td><td>+1%</td><td>26%</td><td>43%</td><td>15%</td><td>1.6%</td></tr><tr><td><strong>ICP</strong></td><td><strong>1,661</strong></td><td><strong>+83%</strong></td><td>11%</td><td><strong>82%</strong></td><td><strong>91%</strong></td><td>0.7%</td></tr><tr><td>Cosmos</td><td>1,449</td><td>-37%</td><td>26%</td><td>29%</td><td>47%</td><td>2.2%</td></tr><tr><td><strong>Stellar</strong></td><td><strong>1,218</strong></td><td><strong>+40%</strong></td><td>20%</td><td>49%</td><td>57%</td><td>0.2%</td></tr><tr><td>Polkadot</td><td>1,090</td><td>-34%</td><td>34%</td><td>25%</td><td>42%</td><td>1.7%</td></tr><tr><td>BNB Chain</td><td>1,074</td><td>-24%</td><td>25%</td><td>44%</td><td>19%</td><td>1.9%</td></tr><tr><td>Optimism</td><td>1,065</td><td>-13%</td><td>22%</td><td>39%</td><td>13%</td><td>1.5%</td></tr><tr><td>Sui</td><td>940</td><td>-20%</td><td>30%</td><td>36%</td><td>45%</td><td><strong>2.5%</strong></td></tr><tr><td>Starknet</td><td>764</td><td>-41%</td><td>24%</td><td>35%</td><td>35%</td><td>0.9%</td></tr><tr><td>TON</td><td>550</td><td>-29%</td><td>27%</td><td>37%</td><td>50%</td><td>1.3%</td></tr></tbody></table><p>*华语占比基于有地理记录的子集，实际值可能更高</p><p><img src="'+h+'" alt="主要生态 YoY 同比增长率（2026-03）"></p><h3 id="如何读这张表" tabindex="-1">如何读这张表 <a class="header-anchor" href="#如何读这张表" aria-label="Permalink to &quot;如何读这张表&quot;">​</a></h3><p><strong>逆势增长的五个协议</strong>：ICP(+83%)、Stellar(+40%)、Base(+25%)、Polygon(+3%)、Arbitrum(+1%)。在整体贡献者数量回调的背景下，这五个协议吸引到了新的贡献者净流入，说明其开源生态仍有真实的建设需求支撑。</p><p><strong>ICP 的隐忧</strong>：+83% YoY，但新人占比 82%、独占率 91%，几乎没有从其他协议迁入的经验贡献者。快速增长背后，社区知识积累的深度有待验证。华语占比仅 0.7%，中文贡献指南几乎为零，是待填补的空白。</p><p><strong>Base 的健康信号</strong>：+25% YoY，新人占比 52%，独占率仅 20%。大量有 EVM 开源经验的开发者同时活跃于 Base，新老贡献者并存，是开源生态健康扩张的理想状态。</p><p><strong>来源印证</strong>：调研报告中，开发者将「生态机会密度」（Grant、Bounty、产品需求）列为选择参与开源协议的首要考量，而非纯粹的技术先进性。开源激励机制的完善程度，直接影响华语贡献者的参与意愿。</p><blockquote><p><em>图：华语开发者入行Web3.0的首要动机（来源：2025 Web3.0华语开发者调研报告）</em><img src="'+i+'" alt="华语开发者入行动机"></p></blockquote><blockquote><p><strong>洞察六</strong>：Web3.0 开源协议的贡献者健康度正在加速分化。衡量一个协议是否值得长期建设的关键指标不是规模，而是贡献者构成：全职贡献者比例（长期可持续性）、新贡献者流入（活力）、跨协议贡献者比例（开放程度）。对华语开源社区而言，Sui（华语贡献者比例最高、需要中文知识基础设施）、Base（贡献门槛低、EVM 通用技能可迁移）、ICP（中文贡献指南几乎为零、空白待填）代表三类不同的建设切入点。</p></blockquote><hr><h2 id="七、华语开发者的开源贡献现状" tabindex="-1">七、华语开发者的开源贡献现状 <a class="header-anchor" href="#七、华语开发者的开源贡献现状" aria-label="Permalink to &quot;七、华语开发者的开源贡献现状&quot;">​</a></h2><p>Web3.0 生态建立在开源协议之上，但「使用开源」和「贡献开源」之间存在巨大鸿沟。理解华语社区在 Web3.0 开源生态中的真实贡献深度，是这份报告对中国开源年度报告最核心的供给。</p><h3 id="_7-1-高度依赖-参与深度不足" tabindex="-1">7.1 高度依赖，参与深度不足 <a class="header-anchor" href="#_7-1-高度依赖-参与深度不足" aria-label="Permalink to &quot;7.1 高度依赖，参与深度不足&quot;">​</a></h3><p>《2025 Web3.0 华语开发者调研报告》揭示了一个典型的「搭便车结构」：几乎所有华语 Web3.0 开发者高度依赖开源组件，但真正长期维护项目的核心贡献者极少。</p><ul><li><strong>提 Issue 的人多，写 PR 的人少</strong>：能阅读代码、发现问题的开发者远多于能提交修复的开发者</li><li><strong>主要参与动机</strong>：学习与技能提升（首位），其次是解决自身遇到的问题</li><li><strong>主要阻碍</strong>：时间不足、路径不清晰、找不到合适的入门项目、英文协作能力不足</li></ul><blockquote><p><em>图：华语开发者对 Web3.0 核心仓库的贡献活跃度（来源：2025 Web3.0华语开发者调研报告）</em><img src="'+p+'" alt="华语开发者核心仓库贡献活跃度"></p></blockquote><p>这一现象的背后，是<strong>中文技术知识基础设施的长期缺位</strong>：优质的中文协议文档、面向初学者的贡献指南、活跃的中文技术讨论社区，是华语开发者从「使用者」成长为「贡献者」的必要条件。</p><h3 id="_7-3-web3-0-开源激励机制的新实验" tabindex="-1">7.3 Web3.0 开源激励机制的新实验 <a class="header-anchor" href="#_7-3-web3-0-开源激励机制的新实验" aria-label="Permalink to &quot;7.3 Web3.0 开源激励机制的新实验&quot;">​</a></h3><p>Web3.0 正在尝试用 Grant、Bounty、Token 奖励和链上声誉系统重塑开源贡献的激励结构，为全球（包括华语）开发者提供了超越传统开源「自愿贡献」模式的新路径。目前这些机制仍在实验阶段，但方向值得关注：</p><ul><li><strong>Grant 计划</strong>（Ethereum Foundation、Solana Foundation 等）：为独立开发者和团队提供协议级贡献资助</li><li><strong>Bounty 平台</strong>（Gitcoin 等）：将具体需求转化为有偿任务，降低贡献门槛</li><li><strong>链上声誉</strong>：贡献记录上链，形成可验证的技术信用积累</li></ul><blockquote><p><strong>洞察七</strong>：华语社区在 Web3.0 开源生态的短板不在于技术能力，而在于参与路径的可见度。建设高质量的中文技术文档、为初级贡献者提供清晰的入门指引、提升 Grant/Bounty 信息的中文触达率，是中国开源社区能够为 Web3.0 全球生态做出的最直接贡献。</p></blockquote><hr><h2 id="八、建议与展望" tabindex="-1">八、建议与展望 <a class="header-anchor" href="#八、建议与展望" aria-label="Permalink to &quot;八、建议与展望&quot;">​</a></h2><p>Web3.0 开源生态的华语参与，已从早期的「跟随者」演变为一支不可忽视的力量。华语开发者在规模上是全球第二大语言群体，在部分协议（Sui、Cosmos）的贡献占比上已超过全球平均水平。但从「规模」到「影响力」，仍有清晰可见的缺口需要填补。</p><h3 id="_8-1-给开发者个体的建议" tabindex="-1">8.1 给开发者个体的建议 <a class="header-anchor" href="#_8-1-给开发者个体的建议" aria-label="Permalink to &quot;8.1 给开发者个体的建议&quot;">​</a></h3><p><strong>选择有中文社区支撑的协议深耕，而非追热点广撒网</strong></p><p>数据表明，华语开发者在 Sui（2.5%）、Cosmos（2.2%）等有成熟中文社区的协议中贡献占比显著更高。选择一个有中文文档、活跃讨论社区和明确贡献路径的协议，系统性积累贡献，比每轮热点都重新起步更有长期回报。</p><p><strong>把「提 Issue」升级为「提 PR」</strong></p><p>调研数据显示，华语开发者的开源参与普遍卡在「发现问题」阶段而非「修复问题」阶段。参与 Dapp-Learning、letsmove 等有组织化贡献路径的学习社区，是从「读者」升级为「贡献者」最低成本的路径，两个仓库合计积累了超过 3,700 个 PR，证明这套路径是可行的。</p><p><strong>英文协作能力是可见度的基础门槛</strong></p><p>华语开发者「在场但不发声」的问题，短期内最可行的改善路径不是等生态方提供中文界面，而是主动参与英文 PR Review 和技术讨论。这是华语贡献者从「代码贡献者」成长为「协议影响者」的必经路径。</p><h3 id="_8-2-给开源社区和生态方的建议" tabindex="-1">8.2 给开源社区和生态方的建议 <a class="header-anchor" href="#_8-2-给开源社区和生态方的建议" aria-label="Permalink to &quot;8.2 给开源社区和生态方的建议&quot;">​</a></h3><p><strong>系统性建设中文知识基础设施，而非一次性翻译</strong></p><p>华语开发者进入一个新协议的最大门槛不是技术难度，而是「找不到可信赖的中文入门资料」。Ethereum 中文文档（ethereum.org/zh）是目前少数做到系统性维护的案例；更多协议（ICP、Stellar、Polkadot）的中文贡献指南几乎为零，这是开源社区可以直接介入的空白。</p><p><strong>把「训练营」和「开源贡献」系统性连接</strong></p><p>OpenBuild、登链学院等平台已验证「训练营结业 = 提交 PR」这套模式的可行性。OpenBuild 9 个训练营仓库积累了 665+ 独立贡献记录，涵盖 6 个生态。WTF Academy 以开源教程形式覆盖 Solidity 和多个 Web3.0 基础栈，GitHub 贡献者体系成熟，是技术入门到开源贡献转化门槛最低的路径之一。706 Creators 和 LXDAO 则代表了另一种模式：以社区共学为核心，将学习过程本身组织化，让参与者在协作中自然形成开源贡献习惯，而非依赖外部激励驱动。将这些不同路径的模式推广至更多协议生态，是华语社区向全球 Web3.0 开源输送贡献者最有效率的方式。</p><p><strong>Grant 和 Bounty 信息的中文触达率需要提升</strong></p><p>调研数据显示，华语开发者将「生态机会密度」列为参与开源的首要考量，但 Ethereum Foundation Grant、Solana Foundation Grant 等核心资助计划的中文信息触达率极低。生态方与华语社区组织建立常态化的信息同步机制，可以直接提升华语贡献者的参与转化率。值得关注的是，GCC（Global Chinese Community of Universal Digital Commons）已在华语社区内建立起面向 Web3.0 开源项目的公共物品捐赠机制，累计资助超过 45 个项目，是华语开发者寻求开源项目资金支持的本土渠道之一。</p><h3 id="_8-3-展望" tabindex="-1">8.3 展望 <a class="header-anchor" href="#_8-3-展望" aria-label="Permalink to &quot;8.3 展望&quot;">​</a></h3><p>2026 年的 Web3.0 开源生态，正处于熊市出清后的「核心建设者时代」。全职贡献者占比创历史新高，逐利型参与者已退场，留下来的是真正关注技术长期价值的开发者。这对华语开源社区是一个难得的机会：喧嚣退去之后，专注于协议底层的持续贡献，正是积累长期话语权的最佳时机。</p><p>华语社区在 Web3.0 开源生态的下一个台阶，不是再造一条华语公链，而是<strong>在全球已形成技术共识的开源协议上，成为不可替代的中文知识基础设施建设者和核心协议贡献者</strong>。</p><blockquote><p><strong>洞察八</strong>：华语开发者对全球 Web3.0 开源生态的贡献，正在从「参与者规模」向「基础设施建设者」转型。中文技术文档、贡献者培养路径、Grant 信息触达，这三类「知识基础设施」的建设质量，将决定华语社区在下一轮 Web3.0 开源周期中的话语权深度。</p></blockquote><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>从 Electric Capital 的开源开发者数据来看，2026 年初的 Web3.0 生态正处于一个关键节点：全球月活贡献者较 2025 年峰值回调约 33%，但全职贡献者占比创历史新高。泡沫出清后，留下的是真正的长期开源建设者。</p><p>对中国开源社区而言，Web3.0 方向有三个值得正视的现实：</p><ol><li><strong>贡献规模被系统性低估</strong>：华语 Web3.0 开源贡献者的真实规模可能是统计数字的 3-4 倍，但在国际开源协议社区中的话语权与贡献规模严重不匹配</li><li><strong>协议选择在成熟化</strong>：华语社区已从早期的热点驱动（BNB Chain）走向更成熟的技术选择（Ethereum、Solana、Sui），开源贡献的长期性在增强</li><li><strong>地理分布在分散化</strong>：开源远程协作文化正在推动贡献者从北上深向全国扩散，本地开源社区的建设成为区域开源生态的核心驱动力</li></ol><p>中国开源社区深度参与 Web3.0 全球协议建设的最大机会，不在于另起炉灶构建封闭生态，而在于<strong>在全球已形成技术共识的开源协议上，系统性建设华语社区的知识基础设施</strong>。高质量的中文协议文档、清晰的贡献者入门指引、活跃的中文技术讨论社区，是将华语开发者从「使用者」转化为「核心贡献者」的关键路径。</p>',134)])])}const y=b(m,[["render",q]]);export{C as __pageData,y as default};
